CREATE POLICY medication_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='medication-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY medication_photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='medication-photos' AND (storage.foldername(name))[1]=auth.uid()::text);
CREATE POLICY medication_photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='medication-photos' AND (storage.foldername(name))[1]=auth.uid()::text);